def original_advanced_source_bytes() -> bytes:
    raw = _SOURCE_JSON.encode("utf-8")
    if hashlib.sha256(raw).hexdigest() != SOURCE_SHA256:
        raise RuntimeError("bundled real chess training corpus checksum changed")
    return raw


def bundled_advanced_puzzles() -> tuple[dict, ...]:
    data = json.loads(original_advanced_source_bytes())
    if (type(data) is not dict
        or data.get("schema") != "accessible-chess-licensed-advanced-training-original-sample-v1"
        or data.get("retained_count") != 16
        or data.get("composed_endgame_studies") is not False
        or data.get("license") != LICENSE_ID
        or type(data.get("puzzles")) is not list
        or len(data["puzzles"]) != 16):
        raise RuntimeError("bundled advanced chess material provenance unavailable")
    return tuple(data["puzzles"])
